<script setup lang="ts">
/**
 * A month grid for choosing a date (`design/components/calendar.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/calendar.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, ref, useId, useTemplateRef, watch } from 'vue'

import * as zag from '@zag-js/date-picker'
import { normalizeProps, useMachine } from '@zag-js/vue'

import { agentDate, agentMember, useDirection } from '@polymorph/vue'
import styles from '@polymorph/recipes/controls/calendar.module.css'
import Button from './Button.vue'

export type FirstDayOfWeek = NonNullable<CalendarProps['firstDayOfWeek']>

export type CalendarDate = zag.CalendarDate

export interface CalendarMessages {
  previousMonth: string
  nextMonth: string
}

export interface CalendarProps {
  /**
   * Names the calendar from outside, as DatePicker's popup does.
   */
  ariaLabel?: string
  ariaLabelledby?: string
  defaultValue?: CalendarDate | null
  /**
   * Disables the whole grid.
   */
  disabled?: boolean
  /**
   * Overrides the locale's first day of the week.
   */
  firstDayOfWeek?: 0 | 1 | 2 | 3 | 4 | 5 | 6
  /**
   * Controlled month navigation, for apps that need it.
   */
  focusedValue?: CalendarDate
  /**
   * App policy, such as booked-out days. Unavailable is not the same as disabled.
   */
  isDateUnavailable?: (date: CalendarDate) => boolean
  /**
   * Drives names, numbering and the week's first day. Defaults to the app's.
   */
  locale?: string
  maxValue?: CalendarDate
  /**
   * Defaults to generic English. Localized hosts pass strings from their catalog.
   */
  messages?: CalendarMessages
  minValue?: CalendarDate
  value?: CalendarDate | null
}

defineOptions({ name: 'Calendar', inheritAttrs: false })

const props = withDefaults(defineProps<CalendarProps>(), {
  disabled: false,
  isDateUnavailable: undefined,
})
const emit = defineEmits<{
  change: [value: CalendarDate | null]
  focusChange: [date: CalendarDate]
}>()
const uid = useId()
const browserLanguage = ref(undefined as string | undefined)
const travel = ref('next')
const shownMonth = ref('')
const monthButton = ref(false)
const root = useTemplateRef<HTMLElement>('root')
const say = computed(
  () => props.messages ?? { previousMonth: 'Previous month', nextMonth: 'Next month' },
)
const language = computed(() => props.locale ?? browserLanguage.value ?? 'en-US')
const english = computed(() => language.value.toLowerCase().startsWith('en'))
const zone = computed(() => Intl.DateTimeFormat().resolvedOptions().timeZone)
const dayName = computed(
  () => (date: zag.DateValue, text: string, today: boolean, selected: boolean) => {
    if (!english.value) return text
    const said = today
      ? selected
        ? `Today, ${text} selected`
        : `Today, ${text}`
      : selected
        ? `${text} selected`
        : text
    if (props.minValue !== undefined && date.compare(props.minValue) === 0)
      return `${said}, First available date`
    if (props.maxValue !== undefined && date.compare(props.maxValue) === 0)
      return `${said}, Last available date`
    return said
  },
)
const documentDirection = useDirection(() => root.value)
const service = useMachine(
  zag.machine,
  computed(() => ({
    id: uid,
    dir: documentDirection.value,
    inline: true,
    locale: language.value,
    timeZone: zone.value,
    value: props.value === undefined ? undefined : props.value === null ? [] : [props.value],
    defaultValue: props.defaultValue == null ? undefined : [props.defaultValue],
    min: props.minValue,
    max: props.maxValue,
    focusedValue: props.focusedValue,
    startOfWeek: props.firstDayOfWeek,
    disabled: props.disabled,
    isDateUnavailable:
      props.isDateUnavailable === undefined
        ? undefined
        : (date) => props.isDateUnavailable?.(date as zag.CalendarDate) === true,
    onValueChange: (details) => {
      emit('change', (details.value[0] as zag.CalendarDate | undefined) ?? null)
    },
    onFocusChange: (details) => {
      emit('focusChange', details.focusedValue as zag.CalendarDate)
    },
    onVisibleRangeChange: (details) => {
      ;((travel.value =
        shownMonth.value !== '' && details.visibleRange.start.toString() < shownMonth.value
          ? 'previous'
          : 'next'),
        (shownMonth.value = details.visibleRange.start.toString()))
    },
  })),
)
const api = computed(() => zag.connect(service, normalizeProps))
const named = computed(() =>
  [props.ariaLabel, api.value.visibleRangeText.formatted].filter(Boolean).join(', '),
)
const monthButtonsOff = computed(
  () =>
    `${api.value.getPrevTriggerProps().disabled === true} ${api.value.getNextTriggerProps().disabled === true}`,
)
const dayOf = computed(() => (date: zag.DateValue) => {
  const cell = api.value.getDayTableCellState({ value: date })
  const off = props.disabled || cell.invalid
  const refused = props.isDateUnavailable?.(date as zag.CalendarDate) === true
  const selected = cell.selected && !off && !refused
  return {
    date,
    cell,
    off,
    unavailable: refused,
    outside: cell.outsideRange,
    selectable: !off && !refused,
    selected,
    name: dayName.value(date, cell.valueText, cell.today, selected),
  }
})
const weeks = computed(() => api.value.weeks.map((week) => week.map((date) => dayOf.value(date))))
const effect1 = () => {
  browserLanguage.value = globalThis.navigator?.language
}
onMounted(effect1)
const effect2 = () => {
  shownMonth.value = api.value.visibleRange.start.toString()
}
onMounted(effect2)
const effect3 = () => {
  monthButton.value &&
    ((held) =>
      held === null || held === document.body || (held as HTMLButtonElement).disabled === true)(
      document.activeElement,
    ) &&
    ((monthButton.value = false),
    requestAnimationFrame(() =>
      root.value?.querySelector<HTMLElement>('[data-calendar-part="day"][tabindex="0"]')?.focus(),
    ))
}
watch(() => monthButtonsOff.value, effect3, { flush: 'post' })
let release4: (() => void) | undefined
const effect4 = () => {
  release4?.()
  const ran = agentMember({
    member: 'Calendar',
    element: () => root.value,
    state: () => ({ value: api.value.value[0]?.toString() ?? '', disabled: props.disabled }),
    actions: {
      set: {
        argument: 'text',
        run: (value) =>
          (() => {
            const date = agentDate(value, {
              min: props.minValue,
              max: props.maxValue,
              unavailable: props.isDateUnavailable,
            })
            api.value.setValue([date])
            api.value.setFocusedValue(date)
          })(),
      },
    },
    withholds: () => root.value,
  })
  release4 = () => {
    ran()
  }
}
onMounted(effect4)
onBeforeUnmount(() => release4?.())
</script>

<template>
  <div
    ref="root"
    v-bind="api.getContentProps()"
    :class="styles.root"
    :hidden="undefined"
    :tabindex="undefined"
    :data-state="undefined"
    role="application"
    :aria-label="named"
    :aria-labelledby="ariaLabelledby"
    data-member="calendar"
  >
    <!-- header -->
    <div
      :class="styles.header"
      @focusin="monthButton = true"
      @focusout="monthButton = ($event.target as HTMLButtonElement).disabled === true"
    >
      <Button
        variant="ghost"
        tone="neutral"
        size="sm"
        :iconOnly="true"
        icon="previous"
        :label="say.previousMonth"
        :disabled="api.getPrevTriggerProps().disabled === true"
        @click="api.goToPrev()"
      />
      <!-- title -->
      <span :class="styles.title" aria-live="polite">
        {{ api.visibleRangeText.formatted }}
      </span>
      <Button
        variant="ghost"
        tone="neutral"
        size="sm"
        :iconOnly="true"
        icon="next"
        :label="say.nextMonth"
        :disabled="api.getNextTriggerProps().disabled === true"
        @click="api.goToNext()"
      />
    </div>
    <!-- grid -->
    <table
      v-bind="api.getTableProps()"
      :class="styles.grid"
      :key="api.visibleRange.start.toString()"
      :tabindex="undefined"
      :aria-label="named"
      :data-travel="travel"
    >
      <thead aria-hidden="true">
        <tr>
          <template v-for="weekday in api.weekDays" :key="weekday.long">
            <th scope="col" :aria-label="weekday.long">
              <span aria-hidden="true">
                {{ weekday.short }}
              </span>
            </th>
          </template>
        </tr>
      </thead>
      <tbody>
        <template v-for="(week, at) in weeks" :key="at">
          <tr>
            <template v-for="day in week" :key="day.date.toString()">
              <td v-if="day.outside" />
              <td
                v-else
                :class="styles.cell"
                role="gridcell"
                :aria-disabled="!day.selectable ? 'true' : undefined"
                :aria-selected="day.selected ? 'true' : undefined"
              >
                <!-- day -->
                <div
                  v-bind="api.getDayTableCellTriggerProps({ value: day.date })"
                  :class="styles.day"
                  data-calendar-part="day"
                  :aria-label="day.name"
                  :aria-current="day.cell.today ? 'date' : undefined"
                  :tabindex="day.off ? undefined : day.cell.focused ? 0 : -1"
                  :data-selected="day.selected ? '' : undefined"
                  :data-today="day.cell.today ? '' : undefined"
                  :data-unavailable="day.unavailable ? '' : undefined"
                  :data-disabled="day.off ? '' : undefined"
                  @focus="api.setFocusedValue(day.date)"
                  @keydown="
                    $event.key === ' ' &&
                    day.selectable &&
                    ($event.preventDefault(), api.setValue([day.date]))
                  "
                >
                  {{ day.date.day }}
                </div>
              </td>
            </template>
          </tr>
        </template>
      </tbody>
    </table>
  </div>
</template>
